 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    # Replace isolated speckles using the local pattern. Preserve real shapes.
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            same_component = 0
            stack = [(r, c)]
            seen = {(r, c)}
            while stack:
                y, x = stack.pop()
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == v:
                        seen.add((ny,nx)); stack.append((ny,nx))
            if len(seen) != 1:
                continue
            near = [grid[y][x] for y in range(max(0,r-1), min(h,r+2))
                    for x in range(max(0,c-1), min(w,c+2)) if (y,x) != (r,c)]
            orth = [grid[y][x] for y,x in ((r-1,c),(r+1,c),(r,c-1),(r,c+1))
                    if 0 <= y < h and 0 <= x < w]
            counts = Counter(near)
            # A speckle touching a substantial object on two sides belongs to it;
            # otherwise it is background clutter or a local replacement.
            candidates = [x for x,n in Counter(orth).items() if x != bg and n >= 2]
            if candidates:
                out[r][c] = max(candidates, key=lambda x: counts[x])
            else:
                out[r][c] = max(counts, key=lambda x: (counts[x], x == bg))
    return out
